'use strict';

const QUOTE = 0x22;
const CR = 0x0d;
const LF = 0x0a;
const SPACE = 0x20;
const BOM = 0xfeff;

// Parser states.
const RECORD_START = 0; // nothing of the current record read yet
const FIELD_START = 1; // just after a delimiter
const UNQUOTED = 2;
const QUOTED = 3;
// Just read a `"` inside a quoted field: it is either the closing quote or
// the first half of `""`, and only the next character can tell.
const QUOTE_IN_QUOTED = 4;

const EOLS = ['\r\n', '\n'];

/** Malformed CSV input. `line` and `column` are 1-based; columns count UTF-16 code units. */
class CsvError extends Error {
  constructor(message, line, column) {
    super(`${message} at line ${line}, column ${column}`);
    this.name = 'CsvError';
    this.line = line;
    this.column = column;
  }
}

function describe(value) {
  if (typeof value === 'string') return JSON.stringify(value);
  if (value === null) return 'null';
  return typeof value;
}

function checkOptionsObject(options) {
  if (options === null || typeof options !== 'object') {
    throw new TypeError(`options must be an object, received ${describe(options)}`);
  }
}

function resolveDelimiter(delimiter) {
  if (delimiter === undefined) return ',';
  if (
    typeof delimiter !== 'string' ||
    delimiter.length !== 1 ||
    delimiter === '"' ||
    delimiter === '\r' ||
    delimiter === '\n'
  ) {
    throw new TypeError(
      `options.delimiter must be a single character other than '"', CR or LF, received ${describe(delimiter)}`,
    );
  }
  return delimiter;
}

function resolveBoolean(value, name) {
  if (value === undefined) return false;
  if (typeof value !== 'boolean') {
    throw new TypeError(`options.${name} must be a boolean, received ${describe(value)}`);
  }
  return value;
}

function resolveParseOptions(options) {
  checkOptionsObject(options);
  return {
    delimiter: resolveDelimiter(options.delimiter),
    header: resolveBoolean(options.header, 'header'),
    skipEmptyLines: resolveBoolean(options.skipEmptyLines, 'skipEmptyLines'),
  };
}

// Assigning `__proto__` would set the prototype instead of creating a key.
function setOwn(object, key, value) {
  if (key === '__proto__') {
    Object.defineProperty(object, key, { value, writable: true, enumerable: true, configurable: true });
  } else {
    object[key] = value;
  }
}

/**
 * Create a streaming parser. `write(chunk)` returns the records completed by
 * that chunk; `end()` returns the rest. Any throw, or `end()`, closes it.
 */
function createParser(options = {}) {
  const { delimiter, header, skipEmptyLines } = resolveParseOptions(options);
  const delim = delimiter.charCodeAt(0);

  let closed = false;
  let started = false;
  let state = RECORD_START;
  let lastWasCR = false;

  // Positions are tracked as absolute offsets so a column is only computed when needed.
  let offset = 0; // absolute offset of the current chunk's first code unit
  let line = 1;
  let lineStart = 0; // absolute offset of the current line's first code unit
  let recordLine = 1;
  let fieldLine = 1;
  let fieldColumn = 1;

  let fields = [];
  let parts = []; // pieces of the current field from earlier chunks or around `""`
  let columns = null; // header names, once the header record has ended
  const seenColumns = header ? new Set() : null;

  function takeParts() {
    const value = parts.length === 1 ? parts[0] : parts.join('');
    parts = [];
    return value;
  }

  function endField(value) {
    if (seenColumns !== null && columns === null) {
      if (seenColumns.has(value)) {
        throw new CsvError(`Duplicate header name ${JSON.stringify(value)}`, fieldLine, fieldColumn);
      }
      seenColumns.add(value);
    }
    fields.push(value);
  }

  function endRecord(out) {
    const record = fields;
    fields = [];
    if (!header) {
      out.push(record);
      return;
    }
    if (columns === null) {
      columns = record;
      return;
    }
    if (record.length !== columns.length) {
      throw new CsvError(`Expected ${columns.length} fields but found ${record.length}`, recordLine, 1);
    }
    const object = {};
    for (let k = 0; k < columns.length; k++) setOwn(object, columns[k], record[k]);
    out.push(object);
  }

  function feed(chunk) {
    const out = [];
    const n = chunk.length;
    let i = 0;
    if (!started && n > 0) {
      started = true;
      if (chunk.charCodeAt(0) === BOM) {
        i = 1;
        lineStart = 1;
      }
    }
    // Start of the current field's piece within this chunk.
    let segStart = i;

    for (; i < n; i++) {
      const c = chunk.charCodeAt(i);
      if (c === LF && lastWasCR) {
        // Second half of CRLF. The CR already counted the line break and,
        // outside quotes, ended the record; inside quotes the LF stays in the piece.
        lastWasCR = false;
        lineStart = offset + i + 1;
        continue;
      }
      lastWasCR = c === CR;

      switch (state) {
        case RECORD_START:
          if ((c === CR || c === LF) && skipEmptyLines) {
            line++;
            lineStart = offset + i + 1;
            break;
          }
          recordLine = line;
        // falls through
        case FIELD_START:
          fieldLine = line;
          fieldColumn = offset + i - lineStart + 1;
          if (c === QUOTE) {
            state = QUOTED;
            segStart = i + 1;
          } else if (c === delim) {
            endField('');
            state = FIELD_START;
          } else if (c === CR || c === LF) {
            endField('');
            endRecord(out);
            line++;
            lineStart = offset + i + 1;
            state = RECORD_START;
          } else {
            state = UNQUOTED;
            segStart = i;
          }
          break;

        case UNQUOTED:
          if (c === delim || c === CR || c === LF) {
            const piece = chunk.slice(segStart, i);
            if (parts.length === 0) {
              endField(piece);
            } else {
              parts.push(piece);
              endField(takeParts());
            }
            if (c === delim) {
              state = FIELD_START;
            } else {
              endRecord(out);
              line++;
              lineStart = offset + i + 1;
              state = RECORD_START;
            }
          }
          break;

        case QUOTED:
          if (c === QUOTE) {
            parts.push(chunk.slice(segStart, i));
            state = QUOTE_IN_QUOTED;
          } else if (c === CR || c === LF) {
            line++;
            lineStart = offset + i + 1;
          }
          break;

        case QUOTE_IN_QUOTED:
          if (c === QUOTE) {
            // `""`: the second quote starts the next piece, so it is kept as a literal `"`.
            state = QUOTED;
            segStart = i;
          } else if (c === delim) {
            endField(takeParts());
            state = FIELD_START;
          } else if (c === CR || c === LF) {
            endField(takeParts());
            endRecord(out);
            line++;
            lineStart = offset + i + 1;
            state = RECORD_START;
          } else {
            throw new CsvError(
              `Expected a delimiter or line break after the closing quote, found ${JSON.stringify(chunk[i])}`,
              line,
              offset + i - lineStart + 1,
            );
          }
          break;
      }
    }

    if ((state === UNQUOTED || state === QUOTED) && segStart < n) {
      parts.push(chunk.slice(segStart));
    }
    offset += n;
    return out;
  }

  function finish() {
    const out = [];
    switch (state) {
      case QUOTED:
        throw new CsvError('Quoted field is never closed; it opens', fieldLine, fieldColumn);
      case UNQUOTED:
      case QUOTE_IN_QUOTED:
        endField(takeParts());
        endRecord(out);
        break;
      case FIELD_START:
        endField('');
        endRecord(out);
        break;
      case RECORD_START:
        // Empty input, or input ending in a line break: no further record.
        break;
    }
    return out;
  }

  function ensureOpen(method) {
    if (closed) throw new Error(`Cannot call ${method}(): the parser is closed`);
  }

  return {
    write(chunk) {
      ensureOpen('write');
      try {
        if (typeof chunk !== 'string') {
          throw new TypeError(`chunk must be a string, received ${describe(chunk)}`);
        }
        return feed(chunk);
      } catch (error) {
        closed = true;
        throw error;
      }
    },
    end() {
      ensureOpen('end');
      closed = true;
      return finish();
    },
  };
}

/** Parse a whole CSV string into arrays of strings, or objects with `header: true`. */
function parse(text, options = {}) {
  if (typeof text !== 'string') {
    throw new TypeError(`text must be a string, received ${describe(text)}`);
  }
  const parser = createParser(options);
  const records = parser.write(text);
  const rest = parser.end();
  for (let k = 0; k < rest.length; k++) records.push(rest[k]);
  return records;
}

function needsQuotes(s, delimiter) {
  return (
    s.includes(delimiter) ||
    s.includes('"') ||
    s.includes('\r') ||
    s.includes('\n') ||
    s.charCodeAt(0) === SPACE ||
    s.charCodeAt(s.length - 1) === SPACE
  );
}

function formatField(value, delimiter, where) {
  let s;
  if (typeof value === 'string') s = value;
  else if (typeof value === 'number' || typeof value === 'boolean') s = String(value);
  else if (value === null || value === undefined) return '';
  else throw new TypeError(`${where} must be a string, number, boolean, null or undefined, received ${describe(value)}`);
  return needsQuotes(s, delimiter) ? `"${s.replace(/"/g, '""')}"` : s;
}

function formatRecord(values, delimiter, where, isFirstLine) {
  if (values.length === 1) {
    const only = formatField(values[0], delimiter, `${where}[0]`);
    // An empty line would parse as [''] only without skipEmptyLines, so quote it.
    return only === '' ? '""' : quoteLeadingBom(only, isFirstLine);
  }
  const encoded = new Array(values.length);
  for (let k = 0; k < values.length; k++) encoded[k] = formatField(values[k], delimiter, `${where}[${k}]`);
  const text = encoded.join(delimiter);
  if (isFirstLine && text.charCodeAt(0) === BOM) {
    // parse() would drop a leading BOM, so it must sit inside quotes. The first
    // field is unquoted here and has no `"`, so wrapping it is enough.
    encoded[0] = `"${encoded[0]}"`;
    return encoded.join(delimiter);
  }
  return text;
}

function quoteLeadingBom(field, isFirstLine) {
  return isFirstLine && field.charCodeAt(0) === BOM ? `"${field}"` : field;
}

function resolveEol(eol) {
  if (eol === undefined) return '\r\n';
  if (!EOLS.includes(eol)) {
    throw new TypeError(`options.eol must be '\\r\\n' or '\\n', received ${describe(eol)}`);
  }
  return eol;
}

function resolveHeader(header) {
  if (header === undefined || header === false) return null;
  if (!Array.isArray(header)) {
    throw new TypeError(`options.header must be an array of column names, received ${describe(header)}`);
  }
  for (let k = 0; k < header.length; k++) {
    if (typeof header[k] !== 'string') {
      throw new TypeError(`options.header[${k}] must be a string, received ${describe(header[k])}`);
    }
  }
  return header;
}

/**
 * Serialize records to CSV. Every record, including the last, ends with
 * `options.eol`. With `options.header`, object records are written in header order.
 */
function stringify(rows, options = {}) {
  checkOptionsObject(options);
  if (!Array.isArray(rows)) {
    throw new TypeError(`rows must be an array, received ${describe(rows)}`);
  }
  const delimiter = resolveDelimiter(options.delimiter);
  const eol = resolveEol(options.eol);
  const header = resolveHeader(options.header);

  const lines = [];
  if (header !== null) lines.push(formatRecord(header, delimiter, 'options.header', true));
  for (let r = 0; r < rows.length; r++) {
    const row = rows[r];
    let values;
    if (Array.isArray(row)) {
      values = row;
    } else if (header !== null && row !== null && typeof row === 'object') {
      values = new Array(header.length);
      for (let k = 0; k < header.length; k++) {
        values[k] = Object.prototype.hasOwnProperty.call(row, header[k]) ? row[header[k]] : undefined;
      }
    } else {
      const expected = header === null ? 'an array' : 'an array or an object';
      throw new TypeError(`rows[${r}] must be ${expected}, received ${describe(row)}`);
    }
    lines.push(formatRecord(values, delimiter, `rows[${r}]`, lines.length === 0));
  }
  return lines.length === 0 ? '' : lines.join(eol) + eol;
}

module.exports = { parse, createParser, stringify, CsvError };

