'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { parse, CsvError } = require('../src/csv.js');

function assertCsvError(fn, line, column, messagePattern) {
  assert.throws(fn, (error) => {
    assert.ok(error instanceof CsvError, `expected CsvError, got ${error && error.name}`);
    assert.ok(error instanceof Error);
    assert.equal(error.name, 'CsvError');
    assert.deepEqual({ line: error.line, column: error.column }, { line, column });
    if (messagePattern) assert.match(error.message, messagePattern);
    return true;
  });
}

describe('parse: input validation', () => {
  for (const [label, value] of [
    ['undefined', undefined],
    ['null', null],
    ['a number', 42],
    ['a Buffer', Buffer.from('a,b')],
    ['a String object', new String('a,b')],
  ]) {
    it(`throws TypeError when text is ${label}`, () => {
      assert.throws(() => parse(value), TypeError);
    });
  }

  it('returns [] for an empty string', () => {
    assert.deepEqual(parse(''), []);
  });

  it('throws TypeError when options is not an object', () => {
    assert.throws(() => parse('a', null), TypeError);
    assert.throws(() => parse('a', ','), TypeError);
  });

  for (const delimiter of ['', ',,', '"', '\r', '\n', '\r\n', '😀', 5, null]) {
    it(`throws TypeError for delimiter ${JSON.stringify(delimiter)}`, () => {
      assert.throws(() => parse('a', { delimiter }), TypeError);
    });
  }

  it('validates the delimiter even when text is empty', () => {
    assert.throws(() => parse('', { delimiter: '"' }), TypeError);
  });

  it('throws TypeError for non-boolean header or skipEmptyLines', () => {
    assert.throws(() => parse('a', { header: 'yes' }), TypeError);
    assert.throws(() => parse('a', { header: ['a'] }), TypeError);
    assert.throws(() => parse('a', { skipEmptyLines: 1 }), TypeError);
  });

  it('ignores options it does not use, such as eol', () => {
    assert.deepEqual(parse('a\n', { eol: '\n' }), [['a']]);
  });
});

describe('parse: fields and records', () => {
  it('splits fields on commas and records on line breaks', () => {
    assert.deepEqual(parse('a,b,c\n1,2,3'), [
      ['a', 'b', 'c'],
      ['1', '2', '3'],
    ]);
  });

  it('accepts CRLF, LF and CR mixed in one input', () => {
    assert.deepEqual(parse('a\r\nb\nc\rd'), [['a'], ['b'], ['c'], ['d']]);
  });

  it('treats LF followed by CR as two line breaks', () => {
    assert.deepEqual(parse('a\n\rb'), [['a'], [''], ['b']]);
  });

  it('uses a custom delimiter and treats commas as ordinary characters', () => {
    assert.deepEqual(parse('a;b,c\n"x;y";z', { delimiter: ';' }), [
      ['a', 'b,c'],
      ['x;y', 'z'],
    ]);
    assert.deepEqual(parse('a\tb', { delimiter: '\t' }), [['a', 'b']]);
  });

  it('keeps empty fields, including trailing ones', () => {
    assert.deepEqual(parse(',a,,'), [['', 'a', '', '']]);
    assert.deepEqual(parse('a,\nb'), [['a', ''], ['b']]);
    assert.deepEqual(parse(','), [['', '']]);
  });

  it('never trims whitespace', () => {
    assert.deepEqual(parse(' a , b \t\n  '), [[' a ', ' b \t'], ['  ']]);
  });

  it('allows records with different field counts outside header mode', () => {
