    assert.deepEqual(parse('﻿a,b\n'), [['a', 'b']]);
    assert.deepEqual(parse('﻿'), []);
    assert.deepEqual(parse('﻿"a"'), [['a']]);
  });

  it('keeps a BOM that is not the first character', () => {
    assert.deepEqual(parse('a\n﻿b,﻿'), [['a'], ['﻿b', '﻿']]);
  });

  it('counts columns from after the BOM', () => {
    assertCsvError(() => parse('﻿"a"x'), 1, 4);
  });
});

describe('parse: errors', () => {
  it('reports an unclosed quoted field at its opening quote', () => {
    assertCsvError(() => parse('a,"bc'), 1, 3, /unclosed/i);
    assertCsvError(() => parse('x\ny,"a\nb,c'), 2, 3);
    assertCsvError(() => parse('"'), 1, 1);
    assertCsvError(() => parse('"a""'), 1, 1);
  });

  it('reports the character after a closing quote', () => {
    assertCsvError(() => parse('"a"b'), 1, 4, /closing quote/);
    assertCsvError(() => parse('"a" ,b'), 1, 4);
    assertCsvError(() => parse('x,y\n1,"2"3'), 2, 6);
  });

  it('counts line breaks inside quoted fields, with CRLF as one', () => {
    assertCsvError(() => parse('"a\r\nb"x'), 2, 3);
    assertCsvError(() => parse('"a\rb"\n"c"d'), 3, 4);
    assertCsvError(() => parse('"a\n\rb"x'), 3, 3);
  });

  it('counts columns in UTF-16 code units', () => {
    // '😀' is two code units, so the stray 'b' is the seventh.
    assertCsvError(() => parse('😀,"a"b'), 1, 7);
  });

  it('reports the first error in reading order', () => {
    assertCsvError(() => parse('"a"x\n"b'), 1, 4);
    assertCsvError(() => parse('a,b\n1,"2"x,3', { header: true }), 2, 7);
    assertCsvError(() => parse('a,b\n1,2,3\n"x', { header: true }), 2, 1);
  });

  it('puts the position in the message', () => {
    assert.throws(() => parse('"a"b'), { message: /line 1, column 4/ });
  });
});

describe('parse: header mode', () => {
  it('keys later records by the first record', () => {
    assert.deepEqual(parse('name,age\r\nAda,36\r\nAlan,41\r\n', { header: true }), [
      { name: 'Ada', age: '36' },
      { name: 'Alan', age: '41' },
    ]);
  });

  it('returns [] for an input with only a header', () => {
    assert.deepEqual(parse('a,b', { header: true }), []);
    assert.deepEqual(parse('a,b\n', { header: true }), []);
    assert.deepEqual(parse('', { header: true }), []);
  });

  it('reports a duplicate name where the second occurrence starts', () => {
    assertCsvError(() => parse('a,b,a\n1,2,3', { header: true }), 1, 5, /Duplicate header name "a"/);
    assertCsvError(() => parse(',', { header: true }), 1, 2);
    assertCsvError(() => parse('x,"a\nb",y,"a\nb"', { header: true }), 2, 6);
  });

  it('reports a duplicate name before later errors in the header', () => {
    assertCsvError(() => parse('a,a,"b', { header: true }), 1, 3);
    assertCsvError(() => parse('a,a,"b"x', { header: true }), 1, 3);
  });

  it('reports a record with too many or too few fields at its line, column 1', () => {
    assertCsvError(() => parse('a,b\n1,2\n1,2,3', { header: true }), 3, 1, /Expected 2 fields but found 3/);
    assertCsvError(() => parse('a,b\n1', { header: true }), 2, 1);
  });

  it('reports a multi-line record at the line where it starts', () => {
    assertCsvError(() => parse('a,b\n"1\n2"\n', { header: true }), 2, 1);
  });

  it('treats an empty line as a one-field record unless skipEmptyLines is set', () => {
    assertCsvError(() => parse('a,b\n\n1,2', { header: true }), 2, 1);
    assert.deepEqual(parse('a,b\n\n1,2\n\n', { header: true, skipEmptyLines: true }), [{ a: '1', b: '2' }]);
    assert.deepEqual(parse('a\n\n', { header: true }), [{ a: '' }]);
  });

  it('skips leading empty lines before the header with skipEmptyLines', () => {
    assert.deepEqual(parse('\r\n\r\na\r\n1\r\n', { header: true, skipEmptyLines: true }), [{ a: '1' }]);
  });

  it('stores __proto__ as an own key without changing the prototype', () => {
    const [record] = parse('__proto__,b\n1,2', { header: true });
    assert.equal(Object.getPrototypeOf(record), Object.prototype);
    assert.deepEqual(Object.keys(record), ['__proto__', 'b']);
    assert.equal(Object.getOwnPropertyDescriptor(record, '__proto__').value, '1');
  });

  it('works with a custom delimiter and quoted header names', () => {
    assert.deepEqual(parse('"a;b";c\n1;2', { header: true, delimiter: ';' }), [{ 'a;b': '1', c: '2' }]);
  });
});

