'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { createParser, CsvError } = require('../src/csv.js');
const {
  createRandom,
  randomString,
  outcome,
  parse,
  parseInChunks,
  splitAt,
  randomChunks,
} = require('./helpers.js');

describe('createParser: write and end', () => {
  it('returns each record from the write whose chunk holds its line break', () => {
    const parser = createParser();
    assert.deepEqual(parser.write('a,b\nc'), [['a', 'b']]);
    assert.deepEqual(parser.write(',d'), []);
    assert.deepEqual(parser.write('\ne\n'), [['c', 'd'], ['e']]);
    assert.deepEqual(parser.end(), []);
  });

  it('returns a record ended by the end of input from end()', () => {
    const parser = createParser();
    assert.deepEqual(parser.write('a,"b'), []);
    assert.deepEqual(parser.write('"'), []);
    assert.deepEqual(parser.end(), [['a', 'b']]);
  });

  it('returns a record at a trailing CR and swallows the LF in the next chunk', () => {
    const parser = createParser();
    assert.deepEqual(parser.write('a\r'), [['a']]);
    assert.deepEqual(parser.write('\nb'), []);
    assert.deepEqual(parser.end(), [['b']]);
  });

  it('returns [] for an empty chunk', () => {
    const parser = createParser();
    assert.deepEqual(parser.write(''), []);
    assert.deepEqual(parser.end(), []);
  });

  it('returns objects in header mode and never the header itself', () => {
    const parser = createParser({ header: true });
    assert.deepEqual(parser.write('id,na'), []);
    assert.deepEqual(parser.write('me\n1,x\n2'), [{ id: '1', name: 'x' }]);
    assert.deepEqual(parser.end(), []);
  });

  it('checks the field count of the record ended by end()', () => {
    const parser = createParser({ header: true });
    parser.write('a,b\n1');
    assert.throws(() => parser.end(), (error) => error instanceof CsvError && error.line === 2 && error.column === 1);
  });

  it('ignores a BOM only as the first character of the whole input', () => {
    let parser = createParser();
    parser.write('');
    parser.write('﻿a');
    assert.deepEqual(parser.end(), [['a']]);

    parser = createParser();
    parser.write('a');
    parser.write('﻿b');
    assert.deepEqual(parser.end(), [['a﻿b']]);
  });

  it('validates options when it is created', () => {
    assert.throws(() => createParser({ delimiter: '\n' }), TypeError);
    assert.throws(() => createParser(null), TypeError);
  });
});

describe('createParser: closed state', () => {
  it('throws TypeError for a non-string chunk and then stays closed', () => {
    const parser = createParser();
    assert.throws(() => parser.write(Buffer.from('a')), TypeError);
    assert.throws(() => parser.write('a'), { name: 'Error', message: /closed/ });
    assert.throws(() => parser.end(), { name: 'Error', message: /closed/ });
  });

  it('throws on both methods after end()', () => {
    const parser = createParser();
    parser.write('a');
    parser.end();
    assert.throws(() => parser.write('b'), Error);
    assert.throws(() => parser.end(), Error);
  });

  it('throws on both methods after write() throws a CsvError', () => {
    const parser = createParser();
    assert.throws(() => parser.write('"a"x'), CsvError);
    assert.throws(() => parser.write('\n'), { message: /closed/ });
    assert.throws(() => parser.end(), { message: /closed/ });
  });

  it('throws on both methods after end() throws a CsvError', () => {
    const parser = createParser();
    parser.write('"open');
    assert.throws(() => parser.end(), (error) => error instanceof CsvError && error.column === 1);
    assert.throws(() => parser.write(''), { message: /closed/ });
    assert.throws(() => parser.end(), { message: /closed/ });
  });
});

// Inputs chosen for the places a chunk boundary can hurt: CRLF, quotes,
// escaped quotes, the BOM, empty lines, and each kind of error.
const CORPUS = [
  '',
  'a',
  'a,b\r\nc,d\r\n',
  'a\r\n\r\nb\r\r\n\n',
  '﻿a,"b"\r\n',
  '"a""b","c\r\nd"\r\n"""",""',
  'x,"y\r\n\r\nz"",",\n',
  'a"b,c"\n',
  '"a"b',
  '1,2\n"3\r\n4"x',
  '"never closed\r\n',
  'h1,h2\n1,2\n\n3,4\r\n',
  'h,h\n1,2',
  'h1,h2\n1\n"',
  'k;v\r"a;b";"c""d"\r',
  '😀,"é\r\n😀"\r\n',
  ',',
  '\n',
];

const OPTION_SETS = [
  {},
  { skipEmptyLines: true },
  { header: true },
  { header: true, skipEmptyLines: true },
  { delimiter: ';' },
];

function assertSameAsParse(text, chunks, options) {
  const expected = outcome(() => parse(text, options));
  const actual = outcome(() => parseInChunks(chunks, options));
  assert.deepEqual(actual, expected, `chunks ${JSON.stringify(chunks)} with ${JSON.stringify(options)}`);
}

describe('createParser: same result as parse() wherever the input is split', () => {
  it('matches for every two-chunk split of the corpus', () => {
    for (const options of OPTION_SETS) {
      for (const text of CORPUS) {
        for (let p = 0; p <= text.length; p++) assertSameAsParse(text, splitAt(text, [p]), options);
      }
    }
  });

  it('matches for every three-chunk split of the corpus', () => {
    for (const options of OPTION_SETS) {
      for (const text of CORPUS) {
        for (let p = 0; p <= text.length; p++) {
          for (let q = p; q <= text.length; q++) assertSameAsParse(text, splitAt(text, [p, q]), options);
        }
      }
    }
  });

  it('matches when fed one code unit at a time', () => {
    for (const options of OPTION_SETS) {
      for (const text of CORPUS) assertSameAsParse(text, text.split(''), options);
    }
  });

  it('matches on random inputs split into random chunks', () => {
