  it('matches for every two-chunk split of the corpus', () => {
    for (const options of OPTION_SETS) {
      for (const text of CORPUS) {
        for (let p = 0; p <= text.length; p++) assertSameAsParse(text, splitAt(text, [p]), options);
      }
    }
  });

  it('matches for every three-chunk split of the corpus', () => {
    for (const options of OPTION_SETS) {
      for (const text of CORPUS) {
        for (let p = 0; p <= text.length; p++) {
          for (let q = p; q <= text.length; q++) assertSameAsParse(text, splitAt(text, [p, q]), options);
        }
      }
    }
  });

  it('matches when fed one code unit at a time', () => {
    for (const options of OPTION_SETS) {
      for (const text of CORPUS) assertSameAsParse(text, text.split(''), options);
    }
  });

  it('matches on random inputs split into random chunks', () => {
    const random = createRandom(0xc5f);
    const alphabet = ['a', 'b', ',', ';', '"', '"', '\r', '\n', ' ', '﻿', '😀'];
    for (let run = 0; run < 3000; run++) {
      const text = randomString(random, alphabet, 40);
      const options = OPTION_SETS[run % OPTION_SETS.length];
      assertSameAsParse(text, randomChunks(random, text, 6), options);
    }
  });
});

describe('createParser: cost stays proportional to the input', () => {
  it('handles a 300 000-chunk quoted field without re-reading earlier input', { timeout: 10000 }, () => {
    // Re-scanning buffered input on each write would be ~4.5e10 steps here.
    // The chunks cycle x, ", " so each escaped quote is split across two writes.
    const cycle = ['x', '"', '"'];
    const count = 300000;
    const parser = createParser();
    assert.deepEqual(parser.write('"'), []);
    for (let k = 0; k < count; k++) assert.equal(parser.write(cycle[k % 3]).length, 0);
    parser.write('"');
    assert.deepEqual(parser.end(), [['x"'.repeat(count / 3)]]);
  });

  it('parses 100 000 records streamed in small chunks', { timeout: 10000 }, () => {
    const text = 'id,"note, quoted"\r\n'.repeat(100000);
    const parser = createParser();
    let total = 0;
    for (let start = 0; start < text.length; start += 7) total += parser.write(text.slice(start, start + 7)).length;
