'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { stringify } = require('../src/csv.js');

describe('stringify: input validation', () => {
  it('throws TypeError when rows is not an array', () => {
    for (const rows of [undefined, null, 'a,b', { 0: ['a'] }]) {
      assert.throws(() => stringify(rows), TypeError);
    }
  });

  it('throws TypeError for a record that is not an array without a header', () => {
    assert.throws(() => stringify([{ a: 1 }]), { name: 'TypeError', message: /rows\[0\] must be an array/ });
    assert.throws(() => stringify([['a'], 'b']), { name: 'TypeError', message: /rows\[1\]/ });
    assert.throws(() => stringify([null]), TypeError);
  });

  for (const [label, value] of [
    ['a bigint', 1n],
    ['a symbol', Symbol('s')],
    ['an object', { a: 1 }],
    ['an array', ['nested']],
    ['a function', () => 'x'],
    ['a Date', new Date(0)],
  ]) {
    it(`throws TypeError for ${label} value and names its position`, () => {
      assert.throws(() => stringify([['ok', value]]), { name: 'TypeError', message: /rows\[0\]\[1\]/ });
    });
  }

  for (const eol of ['\r', '', '\n\r', 'x', null, 10]) {
    it(`throws TypeError for eol ${JSON.stringify(eol)}`, () => {
      assert.throws(() => stringify([['a']], { eol }), TypeError);
    });
  }

  for (const delimiter of ['', ';;', '"', '\r', '\n', 0]) {
    it(`throws TypeError for delimiter ${JSON.stringify(delimiter)}`, () => {
      assert.throws(() => stringify([['a']], { delimiter }), TypeError);
    });
  }

  it('validates options even when there are no rows', () => {
    assert.throws(() => stringify([], { eol: '\r' }), TypeError);
  });

  it('throws TypeError for a header that is not an array of strings', () => {
    assert.throws(() => stringify([], { header: true }), TypeError);
    assert.throws(() => stringify([], { header: 'a,b' }), TypeError);
    assert.throws(() => stringify([], { header: ['a', 1] }), { message: /options\.header\[1\]/ });
  });

  it('throws TypeError when options is not an object', () => {
    assert.throws(() => stringify([], null), TypeError);
  });
});

describe('stringify: output', () => {
  it('returns an empty string for no rows', () => {
    assert.equal(stringify([]), '');
  });

  it('joins records with CRLF by default and ends with one eol', () => {
    assert.equal(stringify([['a', 'b'], ['c', 'd']]), 'a,b\r\nc,d\r\n');
  });

  it('uses LF when eol is "\\n"', () => {
    assert.equal(stringify([['a'], ['b']], { eol: '\n' }), 'a\nb\n');
  });

  it('writes numbers and booleans with String() and null or undefined as empty', () => {
    assert.equal(stringify([[1, 2.5, -0, NaN, true, false, null, undefined]]), '1,2.5,0,NaN,true,false,,\r\n');
  });

  it('writes holes in sparse arrays as empty fields', () => {
    // eslint-disable-next-line no-sparse-arrays
    assert.equal(stringify([['a', , 'c']]), 'a,,c\r\n');
  });

  it('quotes fields containing the delimiter, a quote, CR or LF', () => {
    assert.equal(stringify([['a,b', 'say "hi"', 'x\ry', 'x\ny']]), '"a,b","say ""hi""","x\ry","x\ny"\r\n');
  });

  it('quotes fields that begin or end with a space, and only those', () => {
    assert.equal(stringify([[' a', 'b ', 'c d', '\te', ' ']]), '" a","b ",c d,\te," "\r\n');
  });

  it('writes a record whose only field is empty as ""', () => {
    assert.equal(stringify([[''], [null], ['a']]), '""\r\n""\r\na\r\n');
  });

  it('writes an empty record as an empty line and two empty fields as a lone delimiter', () => {
    assert.equal(stringify([[], ['', '']]), '\r\n,\r\n');
  });

  it('uses a custom delimiter for joining and quoting', () => {
    assert.equal(stringify([['a,b', 'c;d', 'e']], { delimiter: ';' }), 'a,b;"c;d";e\r\n');
    assert.equal(stringify([['a b', 'c']], { delimiter: ' ' }), '"a b" c\r\n');
  });

  it('keeps unicode text as is', () => {
    assert.equal(stringify([['é', '日本', '😀']]), 'é,日本,😀\r\n');
  });

  it('quotes a leading BOM so parse() does not drop it', () => {
    assert.equal(stringify([['﻿a', 'b'], ['﻿c']]), '"﻿a",b\r\n﻿c\r\n');
    assert.equal(stringify([['﻿']]), '"﻿"\r\n');
    assert.equal(stringify([['', 'a']], { delimiter: '﻿' }), '""﻿a\r\n');
  });
});

describe('stringify: header option', () => {
  const header = ['id', 'name'];

  it('writes the header row, then object values in header order', () => {
    assert.equal(
      stringify([{ name: 'Ada', id: 1 }, { id: 2, name: 'Alan, T.' }], { header }),
      'id,name\r\n1,Ada\r\n2,"Alan, T."\r\n',
    );
  });

  it('writes a missing or inherited key as an empty field and ignores extra keys', () => {
    assert.equal(stringify([{ id: 1, extra: 'x' }], { header }), 'id,name\r\n1,\r\n');
    assert.equal(stringify([{}], { header: ['toString'] }), 'toString\r\n""\r\n');
  });

  it('accepts array records next to object records', () => {
    assert.equal(stringify([['1', 'a'], { id: 2 }], { header }), 'id,name\r\n1,a\r\n2,\r\n');
  });

  it('writes only the header row when there are no records', () => {
    assert.equal(stringify([], { header, eol: '\n' }), 'id,name\n');
  });

  it('quotes header names like any other field', () => {
    assert.equal(stringify([], { header: ['a,b', ''] }), '"a,b",\r\n');
    assert.equal(stringify([], { header: [''] }), '""\r\n');
  });

  it('reads own __proto__ keys', () => {
    const row = JSON.parse('{"__proto__": "p"}');
    assert.equal(stringify([row], { header: ['__proto__'] }), '__proto__\r\np\r\n');
  });

  it('still rejects non-object records and bad values', () => {
    assert.throws(() => stringify([42], { header }), { message: /rows\[0\] must be an array or an object/ });
    assert.throws(() => stringify([{ id: {} }], { header }), { message: /rows\[0\]\[0\]/ });
  });
});

