'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { parse, stringify } = require('../src/csv.js');
const { createRandom, randomString, parseInChunks, randomChunks } = require('./helpers.js');

// Every character that stringify or parse treats specially, plus multi-unit text.
const ALPHABET = ['a', 'Z', ',', ';', '\t', ' ', '"', '\r', '\n', '﻿', 'é', '😀'];

const OPTION_SETS = [
  {},
  { skipEmptyLines: true },
  { eol: '\n' },
  { eol: '\n', skipEmptyLines: true },
  { delimiter: ';' },
  { delimiter: '\t', skipEmptyLines: true },
  { delimiter: ' ' },
  { delimiter: '﻿' },
];

function randomRows(random) {
  const rows = [];
  const rowCount = Math.floor(random() * 5);
  for (let r = 0; r < rowCount; r++) {
    const row = [];
    const fieldCount = 1 + Math.floor(random() * 4);
    // Short fields make empty strings and single special characters common.
    for (let f = 0; f < fieldCount; f++) row.push(randomString(random, ALPHABET, random() < 0.5 ? 2 : 8));
    rows.push(row);
  }
  return rows;
}

describe('round trip: parse(stringify(rows, opts), opts)', () => {
  it('returns the rows for hand-picked awkward records', () => {
    const rows = [[''], ['', ''], [' '], ['"'], ['\r\n'], ['﻿'], ['a,b', ' x ', 'say "hi"'], ['\r', '\n\r']];
    for (const options of OPTION_SETS) assert.deepEqual(parse(stringify(rows, options), options), rows);
  });

  it('returns the rows for random records with every option set', () => {
    const random = createRandom(4180);
    for (let run = 0; run < 4000; run++) {
      const rows = randomRows(random);
      const options = OPTION_SETS[run % OPTION_SETS.length];
      const text = stringify(rows, options);
      assert.deepEqual(parse(text, options), rows, `text ${JSON.stringify(text)} with ${JSON.stringify(options)}`);
    }
  });

  it('returns the rows through the streaming parser in random chunks', () => {
    const random = createRandom(7);
    for (let run = 0; run < 1000; run++) {
      const rows = randomRows(random);
      const options = OPTION_SETS[run % OPTION_SETS.length];
      const chunks = randomChunks(random, stringify(rows, options), 5);
      assert.deepEqual(parseInChunks(chunks, options), rows);
    }
  });

  it('returns header objects with header: true on the parse side', () => {
    const header = ['id', 'note', '__proto__'];
    const records = [
      { id: '1', note: 'multi\r\nline, "quoted"', __proto__: 'kept' },
      { id: '', note: ' ', __proto__: '' },
    ].map((record) => JSON.parse(JSON.stringify(record)));
    const text = stringify(records, { header });
    assert.deepEqual(parse(text, { header: true }), records);
  });
});
EOF
