/** Parse a whole CSV string into arrays of strings, or objects with `header: true`. */
function parse(text, options = {}) {
  if (typeof text !== 'string') {
    throw new TypeError(`text must be a string, received ${describe(text)}`);
  }
  const parser = createParser(options);
  const records = parser.write(text);
  const rest = parser.end();
  for (let k = 0; k < rest.length; k++) records.push(rest[k]);
  return records;
}

function needsQuotes(s, delimiter) {
  return (
    s.includes(delimiter) ||
    s.includes('"') ||
    s.includes('\r') ||
    s.includes('\n') ||
    s.charCodeAt(0) === SPACE ||
    s.charCodeAt(s.length - 1) === SPACE
  );
}

function formatField(value, delimiter, where) {
  let s;
  if (typeof value === 'string') s = value;
  else if (typeof value === 'number' || typeof value === 'boolean') s = String(value);
  else if (value === null || value === undefined) return '';
  else throw new TypeError(`${where} must be a string, number, boolean, null or undefined, received ${describe(value)}`);
  return needsQuotes(s, delimiter) ? `"${s.replace(/"/g, '""')}"` : s;
}

function formatRecord(values, delimiter, where, isFirstLine) {
  if (values.length === 1) {
    const only = formatField(values[0], delimiter, `${where}[0]`);
    // An empty line would parse as [''] only without skipEmptyLines, so quote it.
    return only === '' ? '""' : quoteLeadingBom(only, isFirstLine);
  }
  const encoded = new Array(values.length);
  for (let k = 0; k < values.length; k++) encoded[k] = formatField(values[k], delimiter, `${where}[${k}]`);
  const text = encoded.join(delimiter);
  if (isFirstLine && text.charCodeAt(0) === BOM) {
    // parse() would drop a leading BOM, so it must sit inside quotes. The first
    // field is unquoted here and has no `"`, so wrapping it is enough.
    encoded[0] = `"${encoded[0]}"`;
    return encoded.join(delimiter);
  }
  return text;
}

function quoteLeadingBom(field, isFirstLine) {
  return isFirstLine && field.charCodeAt(0) === BOM ? `"${field}"` : field;
}

function resolveEol(eol) {
  if (eol === undefined) return '\r\n';
  if (!EOLS.includes(eol)) {
    throw new TypeError(`options.eol must be '\\r\\n' or '\\n', received ${describe(eol)}`);
  }
  return eol;
}

function resolveHeader(header) {
  if (header === undefined || header === false) return null;
  if (!Array.isArray(header)) {
    throw new TypeError(`options.header must be an array of column names, received ${describe(header)}`);
